import{z as n,x as l,o as e,c as s,q as A,j as B,D as E,d as r,s as i,S as o}from"./chunks/framework.C8m1ZpeB.js";const D=JSON.parse('{"title":"多边机制设计","description":"","frontmatter":{"title":"多边机制设计","date":"2026-09-18T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/ct-multilateral-mechanism.md","filePath":"econ/ct-multilateral-mechanism.md","lastUpdated":1791063341000}'),m={name:"econ/ct-multilateral-mechanism.md"};function c(d,a,p,h,C,f){const t=l("Mermaid");return e(),s("div",null,[a[2]||(a[2]=A('<h1 id="多边机制设计" tabindex="-1">多边机制设计 <a class="header-anchor" href="#多边机制设计" aria-label="Permalink to &quot;多边机制设计&quot;">​</a></h1><div class="epigraph"><p>好机制让每一条不被期望的结局都有人愿意拆台；实施理论把「好规则」重定义成自我执行的法庭。</p><footer>—— 据 Maskin, Review of Economic Studies, 1999（1977 稿）整理</footer></div><p><a href="/econ/ct-dynamic-contracts">上一课</a>把时间写进合同，本课把人数写进机制。双边合同之上是团队、联盟与投票：产出不可分到个人、偏好要加总、代理人之间可以串通。工具箱已在基础课配齐——<a href="/econ/revelation-principle">显示原理</a>把设计归约到 IC 直接机制，<a href="/econ/vcg-pivot">VCG</a> 有效但亏预算，<a href="/econ/agv-mechanism">AGV</a> 平衡预算却只保贝叶斯激励，<a href="/econ/gibbard-satterthwaite">Gibbard–Satterthwaite</a> 宣判无货币时占优策略实施几乎只剩独裁。本课处理工具箱之间的三道缝：不靠货币怎么实施、预算平衡与有效的死结、合谋与俘获。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>三道缝各有一个缺口。第一，公共选择大多没有货币：投票、委员会、宪政规则，VCG 的转移写不出来；占优策略被 G–S 判了死刑后，能否退一档，只要求均衡结果是社会的目标函数？第二，预算平衡与效率的死结：<a href="/econ/myerson-satterthwaite">双边不可能</a>已证，多人时 AGV 用期望外部性转移绕开，但绕开的代价是什么、为什么转移必须依赖他人的报告，需要说清而不是背结论。第三，人数是双刃剑：团队生产让免费搭车与合谋同时成为可能——监督者本身也是代理人，链条每一环都要激励。</p><p><span class="marginnote">直觉类比：纳什实施就是造一台「想错都难」的机器——不管大家怎么博弈，凡是停下来不动的局面，落点都恰好是社会想要的那一个。 Maskin 的条件（单调性、三人、无否决）回答的是「这样的机器什么时候造得出来」。</span></p><h3 id="纳什实施" tabindex="-1">纳什实施 <a class="header-anchor" href="#纳什实施" aria-label="Permalink to &quot;纳什实施&quot;">​</a></h3><p>不靠货币的实施退到均衡概念上。机制 \\(g\\) 纳什实施目标 \\(f\\)，要求每个偏好剖面下 \\(g\\) 的均衡结果集恰好等于 \\(\\{f(\\theta)\\}\\)：不期望的结局必须有人有严格动机偏离。Maskin 在 1999 年（1977 稿）给出刻画：单调性是必要条件——若 \\(f(\\theta)=a\\) 而 \\(a\\) 在另一剖面 \\(\\theta&#39;\\) 下排序没有变差，则 \\(f(\\theta&#39;)=a\\)；加上无否决与三人以上，单调性也充分。单调性弱到多数经济环境都满足，真正卡住的是三人条件与构造的工程性：证明定理用的整数博弈离可上街的规则很远。</p><p><span class="marginnote">整数博弈式构造是存在性证明，不是施工图：任何人报出异常大的整数就触发循环惩罚。它的价值在告诉你空间里有解，真实机制则在邻近处找不需要的那种报复。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>预算死结用会计讲清。VCG 的转移付给「他人报告的外部性」，有效率但净支出为正；要平衡预算，就得让每个人收到的钱来自别人的缴费——AGV 把枢轴税换成期望外部性的对称分摊，预算平衡了，激励却从占优退到贝叶斯。共同的结构是：抽信息租金的钱必须在人群内部流转，谁的转移独立于他人报告，谁就把租金缺口留给设计者。这是<a href="/econ/public-goods-free-rider">公共品自愿供给</a>失败的设计学翻面：免费搭车是均衡，收钱机制必须自己养自己。</p>',11)),(e(),B(o,null,{default:E(()=>[i(t,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20GOAL%5B%22%E7%A4%BE%E4%BC%9A%E7%9B%AE%E6%A0%87%20f(%CE%B8)%22%5D%20--%3E%20M1%7B%22%E6%9C%89%E8%B4%A7%E5%B8%81%EF%BC%9F%22%7D%0A%20%20M1%20--%3E%7C%E6%98%AF%7C%20VCG%5B%22VCG%20%E6%9C%89%E6%95%88%E4%BD%86%E4%BA%8F%E9%A2%84%E7%AE%97%22%5D%0A%20%20M1%20--%3E%7C%E5%90%A6%7C%20NASH%5B%22%E7%BA%B3%E4%BB%80%E5%AE%9E%E6%96%BD%EF%BC%9A%E5%8D%95%E8%B0%83%E6%80%A7%20%2B%20%E4%B8%89%E4%BA%BA%20%2B%20%E6%97%A0%E5%90%A6%E5%86%B3%22%5D%0A%20%20VCG%20--%3E%20AGV%5B%22AGV%20%E6%8D%A2%E6%9C%9F%E6%9C%9B%E5%A4%96%E9%83%A8%E6%80%A7%E5%88%86%E6%91%8A%EF%BC%8C%E9%A2%84%E7%AE%97%E5%B9%B3%E8%A1%A1%22%5D%0A%20%20AGV%20--%3E%20COLL%7B%22%E4%BB%A3%E7%90%86%E4%BA%BA%E5%8F%AF%E5%90%88%E8%B0%8B%EF%BC%9F%22%7D%0A%20%20NASH%20--%3E%20COLL%0A%20%20COLL%20--%3E%7C%E6%98%AF%7C%20CP%5B%22%E6%8A%8A%E5%90%88%E8%B0%8B%E6%97%A0%E5%88%A9%E5%8F%AF%E5%9B%BE%E5%86%99%E8%BF%9B%20IC%20%E7%BA%A6%E6%9D%9F%22%5D%0A%20%20COLL%20--%3E%7C%E5%90%A6%7C%20DONE%5B%22%E6%9C%BA%E5%88%B6%E6%8C%89%20IC%E2%80%93IR%20%E6%B1%82%E8%A7%A3%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=A('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>合谋把「多边」从资源变成问题。Holmström 在 1982 年指出团队生产的死结：预算平衡的分成让个人边际回报只有边际产品的一角，偷懒是均衡；要破预算（局外人拿走或贴补剩余）才买得回效率，与<a href="/econ/common-pool">公地悲剧</a>的会计同源。合谋侧，Tirole 在 1986 年把层级写成信息串通的管道：监督者的证词也是一份报告，可以私下与被监督者对齐；让子联盟无利可图（合谋无利可图约束）要付出真租金。Laffont 与 Tirole 在 1991 年把同一逻辑推进到俘获：规制者被产业收买时，利益集团政治是层级激励失败的宏观形态。</p><p><span class="marginnote">监督链条的每环都要 IC，这是多边与单边的本质差：单边模型里委托人是机制本身、不用被激励；层级一深，委托人分裂成会合谋的代理人串，设计变量从合同矩阵变成组织结构。</span></p><p><span class="marginnote">数字实例：三人团队多干一单位力气能多产出 1 元，平分成三份后自己只拿 0.33 元，另外 0.67 元白送队友——于是人人选择少干。若引入局外人拿走剩余再定额发工资，多干一单位自己实收 1 元，效率才回来：这就是「要破预算才买得回努力」的算术。</span></p>',4)),(e(),B(o,null,{default:E(()=>[i(t,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20TEAM%5B%22%E5%9B%A2%E9%98%9F%E4%BA%A7%E5%87%BA%E4%B8%8D%E5%8F%AF%E5%88%86%E5%88%B0%E4%B8%AA%E4%BA%BA%22%5D%20--%3E%20Q%7B%22%E9%A2%84%E7%AE%97%E6%98%AF%E5%90%A6%E5%B9%B3%E8%A1%A1%EF%BC%9F%22%7D%0A%20%20Q%20--%3E%7C%22%E5%B9%B3%E8%A1%A1%22%7C%20SH%5B%22%E4%B8%AA%E4%BA%BA%E5%9B%9E%E6%8A%A5%E5%8F%AA%E6%9C%89%E8%BE%B9%E9%99%85%E4%BA%A7%E5%93%81%E7%9A%84%E4%B8%80%E8%A7%92%22%5D%0A%20%20SH%20--%3E%20SL%5B%22%E5%81%B7%E6%87%92%E6%88%90%E4%B8%BA%E5%9D%87%E8%A1%A1%22%5D%0A%20%20Q%20--%3E%7C%22%E7%A0%B4%E9%A2%84%E7%AE%97%22%7C%20OUT%5B%22%E5%B1%80%E5%A4%96%E4%BA%BA%E6%8B%BF%E8%B5%B0%E6%88%96%E8%B4%B4%E8%A1%A5%E5%89%A9%E4%BD%99%22%5D%0A%20%20OUT%20--%3E%20EFF%5B%22%E5%8A%AA%E5%8A%9B%E8%A2%AB%E5%85%A8%E9%A2%9D%E5%9B%9E%E6%8A%A5%EF%BC%8C%E6%95%88%E7%8E%87%E4%B9%B0%E5%9B%9E%22%5D%0A%20%20TEAM%20--%3E%20COL%5B%22%E7%9B%91%E7%9D%A3%E8%80%85%E5%8F%AF%E4%B8%8E%E8%A2%AB%E7%9B%91%E7%9D%A3%E8%80%85%E5%AF%B9%E9%BD%90%E8%AF%81%E8%AF%8D%22%5D%0A%20%20COL%20--%3E%20RENT%5B%22%E4%BB%98%E7%9C%9F%E7%A7%9F%E9%87%91%EF%BC%8C%E8%AE%A9%E5%90%88%E8%B0%8B%E6%97%A0%E5%88%A9%E5%8F%AF%E5%9B%BE%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=A('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>纳什实施假定偏好是共同知识，均衡概念只挡单点偏离；对信息结构稳健的实施、对精炼（子博弈完美、可强实施）的要求，都会收紧结论。两人世界无否决不成立，单调性不足够，G–S 的阴影仍在。AGV 需要共同先验，没有先验时贝叶斯机制写不出来——这与<a href="/econ/bayesian-nash">贝叶斯纳什</a>的先验负担同根。多数票、<a href="/econ/median-voter">中位选民</a>与<a href="/econ/arrow-impossibility">阿罗定理</a>的加总困难当作既定地形，不再重证。下一个应用场是拍卖与匹配：多边机制的正面战场。</p><p><span class="marginnote">常见误区：初学者容易以为 VCG「亏预算」只是记账上的小瑕疵，贴点钱无所谓。实际上缺口随人数增长且必须有人持续垫付，机制会在财政上不可持续；AGV 把这笔账摊给参与者自己养自己，代价是激励从「怎么报都一样」退到「赌别人的类型」。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>无货币的实施退到纳什均衡集：单调性必要，三人加无否决时充分。</li><li>预算平衡与效率的张力由租金会计定：转移必须依赖他人报告，AGV 是其对称解。</li><li>团队生产在预算平衡与破预算之间二选一，免费搭车与公地同一笔账。</li><li>合谋与俘获把监督者变成代理人，层级本身成为设计变量。</li><li>实施定理是存在性证明，工程上街要另付稳健与精炼的代价。</li><li>出处：d&#39;Aspremont and Gérard-Varet, <em>JPubE</em> 1979；Holmström, <em>Bell</em> 1982；Maskin, <em>REStud</em> 1999；Tirole, <em>JLEO</em> 1986；Laffont and Tirole, <em>QJE</em> 1991。</li></ul>',5))])}const F=n(m,[["render",c]]);export{D as __pageData,F as default};
